select * from (select * from kufang_vo


        date>=#{start}


        AND #{end}>=date


        AND cnum>0


        AND station="分站入"

) cond limit #{startIndex},#{pageSize}

select * from (select * from kufang_change1


        date>=#{start}


        AND #{end}>=date


        AND 0>cnum

) cond limit #{startIndex},#{pageSize}

select * from (select * from kufang_change1


        date>=#{start}


        AND #{end}>=date


        AND cname LIKE CONCAT('%',#{Type},'%')

) cond limit #{startIndex},#{pageSize}

select * from (select * from ranwudan


        date>=#{start}


        AND #{end}>=date

) cond limit #{startIndex},#{pageSize}
